CREATE TABLE matching_history (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, student_name VARCHAR(120) NOT NULL, potential_matches INT NOT NULL, needs_review INT NOT NULL, not_eligible INT NOT NULL, checked_at TIMESTAMP NOT NULL, PRIMARY KEY(id), INDEX ix_history_user_date(user_id,checked_at), CONSTRAINT fk_history_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
